=== cart.service.ts ===
import { Injectable, signal } from '@angular/core';

export interface CartItem {
  productId: string;
  productName: string;
  supplierId: string;
  supplierName: string;
  unitPrice: number;
  quantity: number;
}

@Injectable({ providedIn: 'root' })
export class CartService {
  private readonly _items = signal<CartItem[]>([]);
  readonly items = this._items.asReadonly();

  addItem(item: {
    productId: string;
    productName: string;
    supplierId: string;
    supplierName: string;
    unitPrice: number;
    quantity: number;
  }): void {
    this._items.update((items) => {
      const index = items.findIndex((i) => i.productId === item.productId && i.supplierId === item.supplierId);
      if (index === -1) {
        return [...items, { ...item }];
      }
      const updated = [...items];
      updated[index] = { ...updated[index], quantity: updated[index].quantity + item.quantity };
      return updated;
    });
  }
}
=== cart.service.spec.ts ===
import { CartService } from './cart.service';

describe('CartService', () => {
  it('legt bei leerem Warenkorb eine neue Position an', () => {
    const service = new CartService();

    service.addItem({
      productId: 'P1',
      productName: 'Ohrhörer Modell Compact',
      supplierId: 'S1',
      supplierName: 'Lieferant 1',
      unitPrice: 27.5,
      quantity: 2,
    });

    expect(service.items()).toEqual([
      {
        productId: 'P1',
        productName: 'Ohrhörer Modell Compact',
        supplierId: 'S1',
        supplierName: 'Lieferant 1',
        unitPrice: 27.5,
        quantity: 2,
      },
    ]);
  });

  it('legt für dasselbe Produkt bei unterschiedlichen Lieferanten zwei getrennte Positionen an', () => {
    const service = new CartService();

