@if (items().length === 0) {
  <p class="cart__empty">Ihr Warenkorb ist leer.</p>
} @else {
  <section class="cart">
    <ul class="cart__items">
      @for (item of items(); track itemKey(item)) {
        <li class="cart__item">
          <span class="cart__item-name">{{ item.productName }}</span>
          <span class="cart__item-supplier">{{ item.supplierName }}</span>
          <span class="cart__item-unit-price">{{ item.unitPrice | number: '1.2-2' }} €</span>
          <label>
            Menge
            <input
              class="cart__item-quantity-input"
              type="number"
              min="1"
              step="1"
              [value]="item.quantity"
              (change)="onQuantityChange(item, $any($event.target).value)"
            />
          </label>
          <span class="cart__item-line-total">{{ lineTotal(item) | number: '1.2-2' }} €</span>
          <button type="button" class="cart__item-remove" (click)="onRemove(item)">Entfernen</button>
          @if (quantityErrors()[itemKey(item)]; as errorMessage) {
            <p class="cart__item-error">{{ errorMessage }}</p>
          }
        </li>
      }
    </ul>
    <p class="cart__total">Gesamtsumme: {{ totalAmount() | number: '1.2-2' }} €</p>
  </section>
}

